/**
 * Assistant image storage: the bytes never live in Mongo, only a small
 * reference does.
 *
 * Two deployments, one contract:
 * - `s3` (local, on-premise): content-addressed MinIO / S3, with WebP
 *   thumbnails generated by sharp and a signed read route, because an `<img>`
 *   cannot send the bearer token.
 * - `cloudinary` (cloud demo): the asset lives in the dedicated
 *   `CLOUDINARY_SPS_FOLDER/attachments` folder and Cloudinary derives the
 *   thumbnails itself.
 *
 * The read URLs are HMAC-signed and stable (no expiry): the content is
 * addressed by its SHA-256, so a URL only ever yields the exact image that was
 * uploaded. Rotating the signing secret revokes the old URLs.
 */
import { createHmac, timingSafeEqual } from 'node:crypto'
import sharp from 'sharp'
import { ObjectStore, sha256Hex } from '@sps/storage'
import {
  ATTACHMENT_FOLDER,
  attachmentAssetUrl,
  attachmentThumbnailUrl,
  cloudinaryConfigured,
  fetchAttachmentImage,
  uploadAttachmentImage,
} from './cloudinary.js'

export type MediaProvider = 's3' | 'cloudinary'
export type AttachmentVariant = 'full' | 'thumb'

/** Images the assistant accepts; the route and the composer share this list. */
export const ATTACHMENT_MIME_TYPES = ['image/png', 'image/jpeg', 'image/webp', 'image/gif'] as const

const EXT_BY_MIME: Record<string, string> = {
  'image/png': 'png',
  'image/jpeg': 'jpg',
  'image/webp': 'webp',
  'image/gif': 'gif',
}

const MIME_BY_EXT: Record<string, string> = {
  png: 'image/png',
  jpg: 'image/jpeg',
  webp: 'image/webp',
  gif: 'image/gif',
}

/** What sharp reports as the decoded format, mapped to the MIME we serve it as. */
const MIME_BY_FORMAT: Record<string, string> = {
  png: 'image/png',
  jpeg: 'image/jpeg',
  webp: 'image/webp',
  gif: 'image/gif',
}

/** What a saved turn keeps: metadata and URLs, never the image bytes. */
export interface MediaRef {
  /** Content hash for S3, Cloudinary public id for the cloud demo. */
  id: string
  provider: MediaProvider
  mime: string
  name: string
  size: number
  width?: number
  height?: number
  sha256?: string
  /** S3 object key (internal); Cloudinary assets are addressed by `id`. */
  key?: string
  url: string
  thumbnailUrl: string
}

export interface PutMediaInput {
  data: Buffer
  mime: string
  name: string
}

export interface ReadMediaResult {
  /** A stored object, streamed. */
  body?: AsyncIterable<Uint8Array>
  /** A thumbnail generated on demand. */
  data?: Uint8Array
  contentType: string
  contentLength?: number
  etag: string
}

/** One stored image, read back with its public reference rebuilt. */
export interface ResolvedMedia {
  data: Buffer
  ref: MediaRef
}

export interface MediaStore {
  readonly provider: MediaProvider
  put(input: PutMediaInput): Promise<MediaRef>
  /** S3 only: the signed read route. Cloudinary serves the browser directly. */
  read(fileId: string, variant: AttachmentVariant): Promise<ReadMediaResult | null>
  /**
   * Reads an image that was uploaded earlier, so a message can name it by id
   * instead of sending its bytes again. Rebuilds the reference the turn keeps.
   * `null` means the id is not one of ours, or the object is gone.
   */
  resolve(input: { id: string; mime: string; name: string }): Promise<ResolvedMedia | null>
}

/** An invalid image is a client error, not a storage failure. */
export class InvalidImageError extends Error {
  constructor(message = 'The uploaded file is not a readable image.') {
    super(message)
    this.name = 'InvalidImageError'
  }
}

/** `<sha256>.<ext>`, the public identifier of one stored image. */
export function attachmentFileId(sha256: string, mime: string): string {
  const ext = EXT_BY_MIME[mime]
  if (!ext) throw new InvalidImageError(`Unsupported image type: ${mime}`)
  return `${sha256}.${ext}`
}

/** Parses a file id from the read route. Anything else is not a stored image. */
export function parseAttachmentFileId(fileId: string): { sha256: string; mime: string } | null {
  const match = /^([a-f0-9]{64})\.(png|jpg|webp|gif)$/.exec(fileId)
  if (!match) return null
  const sha256 = match[1]!
  const mime = MIME_BY_EXT[match[2]!]!
  return { sha256, mime }
}

export function thumbnailKeyFor(sha256: string): string {
  return `thumbs/${sha256.slice(0, 2)}/${sha256}.webp`
}

/** The HMAC that turns a content hash into a capability URL. */
export function attachmentSignature(secret: string, fileId: string, variant: AttachmentVariant): string {
  return createHmac('sha256', secret).update(`${fileId}:${variant}`).digest('base64url')
}

/** Constant-time check of a read signature. */
export function verifyAttachmentSignature(
  secret: string,
  fileId: string,
  variant: AttachmentVariant,
  signature: string,
): boolean {
  const expected = Buffer.from(attachmentSignature(secret, fileId, variant))
  const given = Buffer.from(signature)
  return given.length === expected.length && timingSafeEqual(expected, given)
}

/** Relative URL of the signed read route; the console prefixes the API origin. */
export function attachmentPath(secret: string, fileId: string, variant: AttachmentVariant): string {
  const signature = attachmentSignature(secret, fileId, variant)
  return `/v1/attachments/${fileId}/${variant}?sig=${encodeURIComponent(signature)}`
}

/** A Cloudinary attachment id is a public id under the attachment folder, named by its SHA-256. */
export function isAttachmentPublicId(id: string): boolean {
  if (!id.startsWith(`${ATTACHMENT_FOLDER}/`) || id.includes('..')) return false
  return /^[a-f0-9]{64}$/.test(id.slice(id.lastIndexOf('/') + 1))
}

/** The bytes of a stored object, whichever shape the adapter returned. */
async function storedBytes(stored: ReadMediaResult): Promise<Buffer | null> {
  if (stored.data) return Buffer.from(stored.data)
  if (!stored.body) return null
  const chunks: Uint8Array[] = []
  for await (const chunk of stored.body) chunks.push(chunk)
  return Buffer.concat(chunks)
}

class S3MediaStore implements MediaStore {
  readonly provider = 's3' as const

  constructor(
    private readonly storage: ObjectStore,
    private readonly signingSecret: string,
    private readonly thumbnailWidth: number,
  ) {}

  async put(input: PutMediaInput): Promise<MediaRef> {
    const { data, mime, name } = input
    const { mime: detected, ...dimensions } = await imageInfo(data)
    if (detected !== mime) throw new InvalidImageError(`The image content is ${detected}, not ${mime}.`)
    const stored = await this.storage.putContentAddressed(data, mime)
    const fileId = attachmentFileId(stored.sha256, mime)
    const thumbnail = await this.makeThumbnail(data, stored.sha256)
    return {
      id: stored.sha256,
      provider: 's3',
      mime,
      name,
      size: stored.size,
      ...dimensions,
      sha256: stored.sha256,
      key: stored.key,
      url: attachmentPath(this.signingSecret, fileId, 'full'),
      thumbnailUrl: attachmentPath(this.signingSecret, fileId, thumbnail ? 'thumb' : 'full'),
    }
  }

  async read(fileId: string, variant: AttachmentVariant): Promise<ReadMediaResult | null> {
    const parsed = parseAttachmentFileId(fileId)
    if (!parsed) return null

    if (variant === 'thumb') {
      const key = thumbnailKeyFor(parsed.sha256)
      const cached = await this.storage.getStream(key)
      if (cached) {
        return {
          body: cached.body,
          contentType: 'image/webp',
          ...(cached.contentLength !== undefined ? { contentLength: cached.contentLength } : {}),
          etag: `"${parsed.sha256}-thumb"`,
        }
      }
      // A thumbnail written before sharp was available, or lost with the bucket:
      // rebuild it from the original rather than answering a broken image.
      const original = await this.storage
        .get(this.storage.keyFor(parsed.sha256, parsed.mime))
        .catch(() => null)
      if (!original) return null
      const thumb = await this.makeThumbnail(Buffer.from(original.data), parsed.sha256)
      if (!thumb) return null
      return { data: thumb, contentType: 'image/webp', etag: `"${parsed.sha256}-thumb"` }
    }

    const original = await this.storage.getStream(this.storage.keyFor(parsed.sha256, parsed.mime))
    if (!original) return null
    return {
      body: original.body,
      contentType: original.contentType ?? parsed.mime,
      ...(original.contentLength !== undefined ? { contentLength: original.contentLength } : {}),
      etag: `"${parsed.sha256}"`,
    }
  }

  async resolve(input: { id: string; mime: string; name: string }): Promise<ResolvedMedia | null> {
    if (!/^[a-f0-9]{64}$/.test(input.id)) return null
    let fileId: string
    try {
      fileId = attachmentFileId(input.id, input.mime)
    } catch {
      return null
    }
    const stored = await this.read(fileId, 'full')
    if (!stored) return null
    const data = await storedBytes(stored)
    if (!data) return null
    const info = await imageInfo(data).catch(() => null)
    // The bytes must be the format the id claims: a client cannot relabel them.
    if (!info || info.mime !== input.mime) return null
    const { mime: _detected, ...dimensions } = info
    return {
      data,
      ref: {
        id: input.id,
        provider: 's3',
        mime: input.mime,
        name: input.name,
        size: data.byteLength,
        ...dimensions,
        sha256: input.id,
        url: attachmentPath(this.signingSecret, fileId, 'full'),
        // The read route rebuilds a missing thumbnail from the original.
        thumbnailUrl: attachmentPath(this.signingSecret, fileId, 'thumb'),
      },
    }
  }

  private async makeThumbnail(data: Buffer, sha256: string): Promise<Buffer | null> {
    try {
      const thumbnail = await sharp(data, { animated: false })
        .rotate()
        .resize({
          width: this.thumbnailWidth,
          height: this.thumbnailWidth,
          fit: 'inside',
          withoutEnlargement: true,
        })
        .webp({ quality: 78 })
        .toBuffer()
      await this.storage.put(thumbnailKeyFor(sha256), thumbnail, 'image/webp')
      return thumbnail
    } catch {
      // A thumbnail is a nicety: the original still renders.
      return null
    }
  }
}

class CloudinaryMediaStore implements MediaStore {
  readonly provider = 'cloudinary' as const

  constructor(private readonly thumbnailWidth: number) {}

  async put(input: PutMediaInput): Promise<MediaRef> {
    const { data, mime, name } = input
    const { mime: detected, ...dimensions } = await imageInfo(data)
    if (detected !== mime) throw new InvalidImageError(`The image content is ${detected}, not ${mime}.`)
    const sha256 = sha256Hex(data)
    const uploaded = await uploadAttachmentImage(data, mime, sha256)
    if (!uploaded) throw new Error('Cloudinary upload failed.')
    return {
      id: uploaded.publicId,
      provider: 'cloudinary',
      mime,
      name,
      size: data.byteLength,
      ...dimensions,
      sha256,
      url: uploaded.url,
      thumbnailUrl: attachmentThumbnailUrl(uploaded.publicId, this.thumbnailWidth),
    }
  }

  async read(): Promise<ReadMediaResult | null> {
    // Cloudinary serves the asset itself: the console never proxies the bytes.
    return null
  }

  async resolve(input: { id: string; mime: string; name: string }): Promise<ResolvedMedia | null> {
    // Only our own folder and content-addressed ids: a client cannot name
    // someone else's asset, or an arbitrary URL, as its message context.
    if (!isAttachmentPublicId(input.id)) return null
    const fetched = await fetchAttachmentImage(input.id)
    if (!fetched) return null
    const info = await imageInfo(fetched.data).catch(() => null)
    // The bytes must be the format the message claims.
    if (!info || info.mime !== input.mime) return null
    const { mime: _detected, ...dimensions } = info
    return {
      data: fetched.data,
      ref: {
        id: input.id,
        provider: 'cloudinary',
        mime: input.mime,
        name: input.name,
        size: fetched.data.byteLength,
        ...dimensions,
        sha256: input.id.slice(input.id.lastIndexOf('/') + 1),
        url: attachmentAssetUrl(input.id),
        thumbnailUrl: attachmentThumbnailUrl(input.id, this.thumbnailWidth),
      },
    }
  }
}

/**
 * Reads the intrinsic size and the decoded format, and refuses bytes that are
 * not an image whatever their declared MIME type. A decoded image is the only
 * thing that reaches the store, so a mislabelled payload cannot be served as
 * `image/png` later.
 */
async function imageInfo(data: Buffer): Promise<{ width?: number; height?: number; mime: string }> {
  try {
    const metadata = await sharp(data, { animated: false }).metadata()
    const mime = MIME_BY_FORMAT[metadata.format ?? '']
    if (!mime) throw new InvalidImageError()
    return {
      ...(metadata.width ? { width: metadata.width } : {}),
      ...(metadata.height ? { height: metadata.height } : {}),
      mime,
    }
  } catch (error) {
    if (error instanceof InvalidImageError) throw error
    throw new InvalidImageError()
  }
}

/**
 * Picks the adapter at boot. A deployment told to use Cloudinary without the
 * credentials (a fork, a self-hosted install) falls back to S3 instead of
 * failing every upload.
 */
export function createMediaStore(options: {
  provider: MediaProvider
  storage: ObjectStore
  signingSecret: string
  thumbnailWidth: number
  warn?: (message: string) => void
}): MediaStore {
  if (options.provider === 'cloudinary') {
    if (cloudinaryConfigured()) return new CloudinaryMediaStore(options.thumbnailWidth)
    options.warn?.('MEDIA_STORE=cloudinary but Cloudinary is not configured: falling back to S3/MinIO.')
  }
  return new S3MediaStore(options.storage, options.signingSecret, options.thumbnailWidth)
}
